const topics = ['café de mañana', 'paseo urbano', 'rutina de lectura', 'outfit casual', 'atardecer en terraza'];
const topic = topics[new Date().getDate() % topics.length];
const identity = 'personaje virtual adulto, ficticio y claramente presentado como generado por IA';
const prompt = `Create a realistic vertical social-media ${topic} scene featuring ${identity}. Natural daylight, candid smartphone photography, coherent face and hair, realistic hands, tasteful everyday clothing, no logos, no minors, no sexualized framing, no real-person likeness, no text embedded in image. 9:16 composition.`;
return [{ json: {
  content_id: `ig-${new Date().toISOString().replace(/[:.]/g, '-')}`,
  media_type: 'image',
  topic,
  prompt,
  caption_draft: `Un momento normal de mi día: ${topic}. Personaje virtual generado con IA.`,
  disclosure_required: true,
  status: 'pending_generation',
  created_at: new Date().toISOString()
} }];

const input = $('Build safe content brief').first().json;
const provider = $json;
return [{ json: { ...input, provider_response: provider, status: 'awaiting_human_approval', media_url: provider.output_url || provider.url || provider.data?.output_url || null, approval_note: 'Revisa realismo, derechos, etiquetado IA y ausencia de personas reales antes de publicar.' } }];
